package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumbers;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** A steward transfers the person to another sheet: they arrive with every grade given them (and its
 *  from-date), their terms, contact and aliases, and their claims with their status, dates, notes,
 *  tags, frozen figures, logs and comments; each claim that had a number gets the other sheet's next,
 *  in the order the claims were opened (by the sheet's today then, then the order they were added).
 *  Figures a statement bound are lost, their statement count starts at 0, and references, holds and
 *  settle batches are not carried. They leave this sheet entirely: patron links (either way), pool
 *  memberships, watches and closed periods' fixed totals are dropped. Refused (nothing written) for
 *  anyone but a steward, a retired person, this sheet's own id or an archived sheet, and when their
 *  name, an alias or their contact is already on the other sheet. */
public class TransferPerson {
    public void transfer(@RequestParam(name = "by", required = false) String by,
            @Val TransferRequest request, @Val Person person, PersonRepository people,
            ClaimRepository claims, PeriodRepository periods, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, RoleRepository roles,
            Out<Transfer> transferred) throws InvalidPersonException {
        String user = by == null ? "" : by;
        String sheetId = person.getSheetId();
        String to = request.to();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new InvalidPersonException("Only a steward can transfer people");
        }
        if (to.equals(sheetId)) {
            throw new InvalidPersonException("A person cannot be transferred to their own sheet");
        }
        if (person.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be transferred");
        }
        if (sheets.isArchived(to)) {
            throw new InvalidPersonException("The sheet is archived: " + to);
        }
        if (people.nameTaken(to, person.getName(), null)
                || person.getAliases().stream().anyMatch((a) -> people.nameTaken(to, a, null))
                || (person.getContact() != null && people.contactTaken(to, person.getContact(), null))) {
            throw new InvalidPersonException("The name, an alias or the contact is already on " + to);
        }
        sheets.open(to, user);
        Rollup before = Rollup.of(to, people, claims, rates, sheets, settings);
        for (long id : claims.transferAll(sheetId, person.getId(), to)) {
            Claim claim = claims.find(to, id);
            claims.renumber(claim, ClaimNumbers.next(claim, claims, periods, settings, sheets));
        }
        people.transfer(person, to);
        transferred.set(new Transfer(person, to, before));
    }
}
package net.officefloor.hq.app.person;

import com.fasterxml.jackson.annotation.JsonIgnore;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet: a name and their grades (A, B or C), each in force from its from-date (the
 *  first from the beginning of time), with {@code grade} the one in force on the sheet's today, the version raised by each saved edit, and
 *  their statements: how many have been taken, and the last one's due-total and date (none until the
 *  first), and the date they are retired from (null: not retired; set at all, they count as retired),
 *  and their holds, by when they were added (their OPEN claims dated within one, and not bound by a
 *  statement, count in no live total; nor, from their retirement date on, do any of their open ones). */
public class Person {
    private final long id;
    private final String sheetId;
    private String name;
    private String grade;
    /** The grades they were given, by from-date (none first). */
    private java.util.List<GradeFrom> grades = new java.util.ArrayList<>();
    /** The grade this request's save records (null: none). */
    private GradeFrom recorded;
    /** Their own terms in whole days (null: none). */
    private Integer terms;
    /** Whether this request's save changed their terms, for its audit line. */
    private boolean termsChanged;
    /** Their contact, trimmed and lower-cased (null: none). */
    private String contact;
    /** Whether this request's save changed their contact, for its audit line. */
    private boolean contactChanged;
    private long version;
    private int statementCount;
    private String statedTotal;
    private String statementDate;
    private String retiredFrom;
    /** Their holds, in the order they were added. */
    private java.util.List<Hold> holds = new java.util.ArrayList<>();
    /** The sheet's today (null: not known). */
    private java.time.LocalDate today;
    /** The ids of the people they name as patrons, in the order named. */
    private java.util.List<Long> patronIds = new java.util.ArrayList<>();
    /** Their aliases, sorted as names are compared. */
    private java.util.List<String> aliases = new java.util.ArrayList<>();
    /** The date the statement this request took was taken as of (null: now), for its audit line. */
    private String statedAsOf;
    /** How many claims the statement this request took bound, for its audit line. */
    private int statedClaims;
    /** The due-total of the statement this request cancelled, for its audit line. */
    private String cancelledTotal;

    public Person(long id, String sheetId, String name, String grade, long version) {
        this(id, sheetId, name, grade, version, 0, null, null);
    }

    public Person(long id, String sheetId, String name, String grade, long version,
            int statementCount, String statedTotal, String statementDate) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
        this.statementCount = statementCount;
        this.statedTotal = statedTotal;
        this.statementDate = statementDate;
    }

    public long getId() { return id; }
